"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[849],{86164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"DocsSidebar":[{"type":"link","label":"Introduction","href":"/docs/getting-started/intro","docId":"getting-started/intro","unlisted":false},{"type":"category","label":"Concepts","items":[{"type":"link","label":"Device Binding","href":"/docs/concepts/device-binding","docId":"concepts/device-binding","unlisted":false},{"type":"link","label":"Devices Screen","href":"/docs/concepts/devices-screen","docId":"concepts/devices-screen","unlisted":false},{"type":"link","label":"Spaces","href":"/docs/concepts/spaces","docId":"concepts/spaces","unlisted":false},{"type":"link","label":"Roles & Permissions","href":"/docs/concepts/roles-permissions","docId":"concepts/roles-permissions","unlisted":false},{"type":"link","label":"How Instant Connect Works","href":"/docs/concepts/dasset-instant-connect","docId":"concepts/dasset-instant-connect","unlisted":false},{"type":"link","label":"DASSET AI","href":"/docs/concepts/dasset-ai","docId":"concepts/dasset-ai","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"User Guide","items":[{"type":"category","label":"Windows & macOS","items":[{"type":"link","label":"Introduction","href":"/docs/user-guide/pc-mac/dasset-introduction","docId":"user-guide/pc-mac/dasset-introduction","unlisted":false},{"type":"link","label":"Installation and Download","href":"/docs/user-guide/pc-mac/dasset-installation","docId":"user-guide/pc-mac/dasset-installation","unlisted":false},{"type":"link","label":"Registration and Login","href":"/docs/user-guide/pc-mac/dasset-registration","docId":"user-guide/pc-mac/dasset-registration","unlisted":false},{"type":"link","label":"Device List Page","href":"/docs/user-guide/pc-mac/dasset-device-list","docId":"user-guide/pc-mac/dasset-device-list","unlisted":false},{"type":"link","label":"Adding/Removing Devices (Binding)","href":"/docs/user-guide/pc-mac/dasset-adding-devices","docId":"user-guide/pc-mac/dasset-adding-devices","unlisted":false},{"type":"category","label":"Device Management","items":[{"type":"link","label":"Device Management","href":"/docs/user-guide/pc-mac/dasset-device-management","docId":"user-guide/pc-mac/dasset-device-management","unlisted":false},{"type":"link","label":"Storage Management","href":"/docs/user-guide/pc-mac/dasset-storage-management","docId":"user-guide/pc-mac/dasset-storage-management","unlisted":false},{"type":"link","label":"Disk Management","href":"/docs/user-guide/pc-mac/dasset-disk-management","docId":"user-guide/pc-mac/dasset-disk-management","unlisted":false},{"type":"link","label":"Node Configuration","href":"/docs/user-guide/pc-mac/dasset-node-configuration","docId":"user-guide/pc-mac/dasset-node-configuration","unlisted":false},{"type":"link","label":"Member Management","href":"/docs/user-guide/pc-mac/dasset-member-management","docId":"user-guide/pc-mac/dasset-member-management","unlisted":false},{"type":"link","label":"Network Management","href":"/docs/user-guide/pc-mac/dasset-network-management","docId":"user-guide/pc-mac/dasset-network-management","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"File Management","href":"/docs/user-guide/pc-mac/dasset-file-management","docId":"user-guide/pc-mac/dasset-file-management","unlisted":false},{"type":"link","label":"File Operations","href":"/docs/user-guide/pc-mac/dasset-file-operations","docId":"user-guide/pc-mac/dasset-file-operations","unlisted":false},{"type":"link","label":"Files Sync & Deduplication","href":"/docs/user-guide/pc-mac/dasset-filessync-dedupe","docId":"user-guide/pc-mac/dasset-filessync-dedupe","unlisted":false},{"type":"category","label":"Applications","items":[{"type":"link","label":"Group Space","href":"/docs/user-guide/pc-mac/dasset-applications-groupspace","docId":"user-guide/pc-mac/dasset-applications-groupspace","unlisted":false},{"type":"link","label":"Task Center","href":"/docs/user-guide/pc-mac/dasset-applications-task-center","docId":"user-guide/pc-mac/dasset-applications-task-center","unlisted":false},{"type":"link","label":"My Favorites","href":"/docs/user-guide/pc-mac/dasset-applications-my-favorites","docId":"user-guide/pc-mac/dasset-applications-my-favorites","unlisted":false},{"type":"link","label":"External Storage","href":"/docs/user-guide/pc-mac/dasset-applications-external-storage","docId":"user-guide/pc-mac/dasset-applications-external-storage","unlisted":false},{"type":"link","label":"Recycle Bin","href":"/docs/user-guide/pc-mac/dasset-applications-recycle-bin","docId":"user-guide/pc-mac/dasset-applications-recycle-bin","unlisted":false},{"type":"link","label":"Offline Download","href":"/docs/user-guide/pc-mac/dasset-applications-offline-download","docId":"user-guide/pc-mac/dasset-applications-offline-download","unlisted":false},{"type":"link","label":"My Shares","href":"/docs/user-guide/pc-mac/dasset-applications-my-shares","docId":"user-guide/pc-mac/dasset-applications-my-shares","unlisted":false},{"type":"link","label":"My Vault","href":"/docs/user-guide/pc-mac/dasset-applications-my-vault","docId":"user-guide/pc-mac/dasset-applications-my-vault","unlisted":false},{"type":"link","label":"Lite NVR","href":"/docs/user-guide/pc-mac/dasset-applications-lite-nvr","docId":"user-guide/pc-mac/dasset-applications-lite-nvr","unlisted":false},{"type":"link","label":"Container Tool","href":"/docs/user-guide/pc-mac/dasset-applications-container-tool","docId":"user-guide/pc-mac/dasset-applications-container-tool","unlisted":false},{"type":"link","label":"Online Document Editing","href":"/docs/user-guide/pc-mac/dasset-applications-online-document","docId":"user-guide/pc-mac/dasset-applications-online-document","unlisted":false},{"type":"link","label":"Cloud Drive","href":"/docs/user-guide/pc-mac/dasset-applications-cloud-drive","docId":"user-guide/pc-mac/dasset-applications-cloud-drive","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Network Discovery Services","href":"/docs/user-guide/pc-mac/dasset-samba","docId":"user-guide/pc-mac/dasset-samba","unlisted":false},{"type":"link","label":"AI Notes","href":"/docs/user-guide/pc-mac/dasset-notes","docId":"user-guide/pc-mac/dasset-notes","unlisted":false},{"type":"category","label":"Instant Messaging","items":[{"type":"link","label":"Instant Messaging (IM)","href":"/docs/user-guide/pc-mac/dasset-im-select-server","docId":"user-guide/pc-mac/dasset-im-select-server","unlisted":false},{"type":"link","label":"Chat Interface Overview","href":"/docs/user-guide/pc-mac/dasset-im-interface-overview","docId":"user-guide/pc-mac/dasset-im-interface-overview","unlisted":false},{"type":"link","label":"Voice & Video Calls","href":"/docs/user-guide/pc-mac/dasset-im-calls","docId":"user-guide/pc-mac/dasset-im-calls","unlisted":false},{"type":"link","label":"One-on-One Chat","href":"/docs/user-guide/pc-mac/dasset-im-1-on-1-chat","docId":"user-guide/pc-mac/dasset-im-1-on-1-chat","unlisted":false},{"type":"link","label":"Group Chat","href":"/docs/user-guide/pc-mac/dasset-im-group-chat","docId":"user-guide/pc-mac/dasset-im-group-chat","unlisted":false},{"type":"link","label":"IM AI Agent","href":"/docs/user-guide/pc-mac/dasset-im-ai-agent","docId":"user-guide/pc-mac/dasset-im-ai-agent","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Lite NAS","href":"/docs/user-guide/pc-mac/dasset-lite-nas","docId":"user-guide/pc-mac/dasset-lite-nas","unlisted":false},{"type":"link","label":"Client Settings & Notifications","href":"/docs/user-guide/pc-mac/dasset-client-settings","docId":"user-guide/pc-mac/dasset-client-settings","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true},{"type":"category","label":"OEMs","items":[{"type":"link","label":"DASSET for OEMs","href":"/docs/oem-odm/oem-opportunity","docId":"oem-odm/oem-opportunity","unlisted":false},{"type":"link","label":"DASSET Software Platform","href":"/docs/oem-odm/oem-software-platform","docId":"oem-odm/oem-software-platform","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"FAQ","href":"/docs/faq/faqs","docId":"faq/faqs","unlisted":false},{"type":"category","label":"Troubleshooting","items":[{"type":"link","label":"Connectivity Errors","href":"/docs/troubleshooting/connectivity","docId":"troubleshooting/connectivity","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Privacy Policy","href":"/docs/privacy-policy/","docId":"privacy-policy/privacy-policy","unlisted":false}]},"docs":{"concepts/dasset-ai":{"id":"concepts/dasset-ai","title":"DASSET AI","description":"Public Cloud AI Services","sidebar":"DocsSidebar"},"concepts/dasset-instant-connect":{"id":"concepts/dasset-instant-connect","title":"How Instant Connect Works","description":"Overview","sidebar":"DocsSidebar"},"concepts/device-binding":{"id":"concepts/device-binding","title":"Device Binding","description":"New DASSET Data Hubs are shipped ready to be setup by the owner of the device. The owner has complete administrative control over how the device is used, including who else may or may not be able to access content on the Data Hub.  Owners of a Data Hub are bound to the device through a process called binding. Only one user account can be bound as the Owner of a Data Hub.","sidebar":"DocsSidebar"},"concepts/devices-screen":{"id":"concepts/devices-screen","title":"Devices Screen","description":"After logging-in to your DASSET user account, you are presented with the Devices Screen, where you manage all aspects of your DASSET user account, such as connecting to devices and changing your account information.","sidebar":"DocsSidebar"},"concepts/roles-permissions":{"id":"concepts/roles-permissions","title":"Roles & Permissions","description":"DASSET uses Role-Based Access Control (RBAC) to control what permissions users of the Data Hub can, or cannot, do.  Each user of the system is assigned a role, either automatically by the system, or specifically by the Owner of the device.","sidebar":"DocsSidebar"},"concepts/spaces":{"id":"concepts/spaces","title":"Spaces","description":"The exposure of the file system in DASSET is designed to present data to the user that only they have access to.  Rather than combing through a tree of file folders containing both user and system files, DASSET easily organizes user\'s data into Spaces.  Spaces are logical representations of data on the Data Hub.","sidebar":"DocsSidebar"},"faq/faqs":{"id":"faq/faqs","title":"FAQs","description":"What exactly is a DASSET Data Hub?","sidebar":"DocsSidebar"},"features/account-settings":{"id":"features/account-settings","title":"Account Settings","description":"Your DASSET User Account can be used on several DASSET Data Hubs, rather than having to create new accounts for each Data Hub you have been invited to join.  If you only have 1 Data Hub, then the relationship between Account and Data Hub is 13."},"features/apps/album-backup":{"id":"features/apps/album-backup","title":"Album Back-up","description":"Bringing all of your data together in a single, secure location is a fundamental tenet of DASSET.  Album Backup provides an easy way to ensure the photos on your phone, tablet or computer, are easily and automatically backed-up to your DASSET Data Hub."},"features/apps/contacts-backup":{"id":"features/apps/contacts-backup","title":"Contacts Back-Up","description":"In addition to data we think of as files and photos, DASSET also offers the ability to back-up other types of data that is important to you - like your contacts on your phone.  Contacts Backup provides a simple way to back-up, and restore, your contacts."},"features/apps/de-duplication":{"id":"features/apps/de-duplication","title":"File De-Duplication","description":"When bringing all of your data together from multiple devices and clouds, it\'s likely that you will have the same file from these locations, copied multiple times to your Data Hub.  Finding these files on your own, and deciding which ones to keep vs. delete can be daunting."},"features/apps/dlna":{"id":"features/apps/dlna","title":"Streaming Media (DLNA)","description":"Your DASSET Data Hub can act as a media server for your home or office, giving you the ability to stream content such as videos and audio to TVs, consoles and stereos that support the DLNA protocol."},"features/apps/external-storage":{"id":"features/apps/external-storage","title":"External Storage","description":"Your DASSET Data Hub has the ability to view and manage data that reside on storage devices that can connect to your Data Hub via USB.  These include portable HDDs, SSDs and thumbdrives.  Rather than copying the contents of these storage devices to your computer first, and then transferring them to your Data Hub, you can simply copy them directly using External Storage."},"features/apps/recycle":{"id":"features/apps/recycle","title":"Recycle Bin","description":"Like most operating systems, DASSET comes with the ability to restore files accidentally deleted by the user.  The Recycle Bin is where all files deleted on the system are placed, giving you the ability to undo those \\"Oops\\" moments of deleting a file inadvertently."},"features/apps/samba":{"id":"features/apps/samba","title":"LAN Access (Samba)","description":"In addition to accessing files on your Data Hub through the DASSET application, the ability to do so directly from a device that supports the SMB networking protocol), such as Windows and Linux/Unix-based Operating Systems like Android and Apple MacOS and iOS.  Samba in DASSET is an implementation of the SMB networking protocol, making it easy to establish file-sharing between your Windows, MacOS or mobile phone and a DASSET Data Hub."},"features/homescreen":{"id":"features/homescreen","title":"Home Screen","description":"After logging into your DASSET user account and connecting to a Data Hub, you are presented with the Home Screen.  The Home Screen is your one-stop shop for accessing all of the functionality of DASSET on the Data Hub you are connected to.  For example, connecting to a Data Hub that you have been invited to join may have a slightly different Home Screen than when you connect to your own Data Hub."},"features/settings/settings-device-info":{"id":"features/settings/settings-device-info","title":"Device Info","description":"The Device info section will provide you with details regarding general information about the Data Hub currently being accessed.  The below shows all of the information available to a user who has the Owner or Manager role for the Data Hub.  Users with the Member role will show less information, with some settings being unavailable."},"features/settings/settings-disk-management":{"id":"features/settings/settings-disk-management","title":"Disk Management","description":"The hard disk drives (HDD), solid-state drives (SSD) and any externally-connected drives installed or connected to your Data Hub are available for configuration in Disk Management.  DASSET supports the ability to configure your drives in a way for optimal performance and redundancy using data storage virtualization technology known as RAID."},"features/settings/settings-disk-self-test":{"id":"features/settings/settings-disk-self-test","title":"Disk Self-Test","description":"Hard Disk Drives (HDD) are mechanical storage devices, and as such, will eventually fail if not replaced.  Known as the Mean Time Between Failure (MTBF), most HDDs have a MTBF between 300,000 and 1,200,000 hours.  When a HDD begins to experience failure due to MTBF, you may see things such as failure to read or write files, or mechanical clicking sounds coming from your HDD."},"features/settings/settings-disk-sleep":{"id":"features/settings/settings-disk-sleep","title":"Disk Sleep","description":"In the Disk Self-Test article, it was explained that disk drives can eventually fail after prolonged use.  A way to extend the life (MTBF) of the disks installed in your Data Hub is to use the Disk Sleep feature to put your disks into a low-power state when your Data Hub is not typically in use.  Your Data Hub is still powered-on and operating normally.  If the Data Hub needs to access data on the disks when they are in the sleep mode, the system will automatically wake-up the disks to read or write data as necessary."},"features/settings/settings-hardware-status":{"id":"features/settings/settings-hardware-status","title":"Hardware Status","description":"Viewing the specific devices of your Data Hub, such as CPU, memory and storage can be found in Hardware Status."},"features/settings/settings-home":{"id":"features/settings/settings-home","title":"Settings Screen","description":"After logging into your account and connecting to a Data Hub, you can access the Settings of the Data Hub to control specific behavior and hardware features of the device.  You can access Settings by clicking on the Settings icon on the DASSET navigation bar."},"features/settings/settings-lan-settings":{"id":"features/settings/settings-lan-settings","title":"LAN Settings","description":"Viewing and configuring how your DASSET Data Hub is accessible on your home or business network is available through the LAN Settings screen."},"features/settings/settings-member-management":{"id":"features/settings/settings-member-management","title":"Member Management","description":"The Member Management screen shows all current users who have joined your Data Hub, as well as the Roles and Permissions they have.  From this screen, Owners and Managers have the ability to modify permissions of users as well as having the ability to add additional users to the Data Hub."},"features/settings/settings-power-management":{"id":"features/settings/settings-power-management","title":"Power Management","description":"There are times when you may want your DASSET Data Hub to be rebooted, or turned completely off for either saving power, upgrading hardware or applying updates to the system, which is accomplished through Power Management."},"features/settings/settings-security-settings":{"id":"features/settings/settings-security-settings","title":"Security Settings","description":"If you want to add additional security to your DASSET Data Hub, you can do so in the Security Settings screen."},"features/settings/settings-share-device":{"id":"features/settings/settings-share-device","title":"Share Device","description":"DASSET Data Hubs provide a simple, yet secure, method for sharing your data with others.  Share Device gives users with the Owner or Manager role to invite a user to join the Data Hub.  When a user accepts an invite to join a Data Hub, they have access to files and applications on the device, based on the roles and permissions they have been assigned."},"getting-started/intro":{"id":"getting-started/intro","title":"Introduction","description":"Our Data Dilemma","sidebar":"DocsSidebar"},"getting-started/introOLD":{"id":"getting-started/introOLD","title":"Introduction","description":"Our data dilemma"},"how-to/getting-started/dasset-app-install":{"id":"how-to/getting-started/dasset-app-install","title":"Install the DASSET app","description":"The DASSET application is the way you access the data and applications on your DASSET Data Hub, or a Data Hub that has been shared with you by other Data Hub users.  Once you have the DASSET application installed, you can configure alternative ways to access your files, such as using SAMBA which allows you to mount your Data Hub as a mapped drive in Windows or MacOS."},"how-to/getting-started/device-set-up":{"id":"how-to/getting-started/device-set-up","title":"Set-up your DASSET Data Hub","description":"Congratulations on the purchase of your DASSET Data Hub!  In this article, you will be guided through the steps of initially setting-up and connecting to your Data Hub using the DASSET application."},"oem-odm/oem-opportunity":{"id":"oem-odm/oem-opportunity","title":"DASSET for OEMs","description":"A \\"Blue Ocean\\" Opportunity in Smart Storage","sidebar":"DocsSidebar"},"oem-odm/oem-software-platform":{"id":"oem-odm/oem-software-platform","title":"DASSET Software Platform","description":"Overview","sidebar":"DocsSidebar"},"privacy-policy/privacy-policy":{"id":"privacy-policy/privacy-policy","title":"Privacy Policy","description":"Update Date: February 26, 2024","sidebar":"DocsSidebar"},"troubleshooting/connectivity":{"id":"troubleshooting/connectivity","title":"Connectivity Errors","description":"","sidebar":"DocsSidebar"},"user-guide/mobile":{"id":"user-guide/mobile","title":"Android & iOS","description":"This document is intended to help users quickly understand the full"},"user-guide/pc-mac":{"id":"user-guide/pc-mac","title":"Windows & macOS","description":"This document serves as a general guide to the DASSET feature set. Please be advised that DASSET functionality is device-specific; hardware constraints may limit the availability of certain modules. Furthermore, PlanetX Labs maintains a policy of continuous integration. Consequently, documentation images and descriptions may differ from the production environment. Users should refer to the live DASSET interface for real-time feature verification and system status."},"user-guide/pc-mac/dasset-adding-devices":{"id":"user-guide/pc-mac/dasset-adding-devices","title":"Adding/Removing Devices (Binding)","description":"You can click the Add Device button on the DASSET home page and enter an invitation code to bind a DASSET device shared by others.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-cloud-drive":{"id":"user-guide/pc-mac/dasset-applications-cloud-drive","title":"Cloud Drive","description":"DASSET supports integration with third-party cloud drives. You can upload files from the DASSET device to a cloud drive, download files from a cloud drive to the device, and synchronize data between them. Currently supported services include Google Drive, OneDrive, and Dropbox.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-container-tool":{"id":"user-guide/pc-mac/dasset-applications-container-tool","title":"Container Tool","description":"Using Docker containers, you can run a variety of third-party applications on the DASSET device to expand its capabilities. The container tool is available only to the Owner account.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-external-storage":{"id":"user-guide/pc-mac/dasset-applications-external-storage","title":"External Storage","description":"When a USB drive is connected to the DASSET device, you can access its data through the External Storage function in the client. Files on the USB drive can be managed in the same way as files in other DASSET spaces. You can enter External Storage by clicking the External Storage icon in the app, or by selecting External Storage from the File Management sidebar.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-groupspace":{"id":"user-guide/pc-mac/dasset-applications-groupspace","title":"Group Space","description":"In Group Space, users with Group Space permissions can create group folders and invite specific members to join. Only members can access files within a group folder, with access controlled by predefined read/write permissions. Group Space is useful when certain photos, videos, or files need to be shared only with selected users. By creating multiple groups, different content can be shared with different users, providing resource sharing and collaboration for families or small teams. Group Space supports multi-device, cross-platform access but does not support Samba access.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-lite-nvr":{"id":"user-guide/pc-mac/dasset-applications-lite-nvr","title":"Lite NVR","description":"The DASSET device supports cameras compatible with the Onvif protocol, enabling centralized management of cameras, storage of surveillance video, real-time and historical video viewing, and PTZ (pan-tilt-zoom) control. You can securely view surveillance footage anytime, anywhere without the privacy risks associated with uploading video to the cloud.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-my-favorites":{"id":"user-guide/pc-mac/dasset-applications-my-favorites","title":"My Favorites","description":"You can add data stored on the DASSET device to My Favorites, allowing quick access at any time. Enter Favorites by clicking the My Favorites icon in the DASSET app, or by selecting My Favorites from the left sidebar in File Management. In Favorites, you can:","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-my-shares":{"id":"user-guide/pc-mac/dasset-applications-my-shares","title":"My Shares","description":"My Shares provides centralized management for all file sharing tasks you created, including Member Sharing and QR Code Sharing.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-my-vault":{"id":"user-guide/pc-mac/dasset-applications-my-vault","title":"My Vault","description":"The My Vault is a secure area within the DASSET device. All files stored in My Vault are protected with strong encryption to ensure security. Without entering the correct password, My Vault cannot be accessed from the DASSET client.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-offline-download":{"id":"user-guide/pc-mac/dasset-applications-offline-download","title":"Offline Download","description":"Offline download allows the DASSET device to run 24/7 to automatically download resources. This feature is available only to Owner and Administrator accounts.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-online-document":{"id":"user-guide/pc-mac/dasset-applications-online-document","title":"Online Document Editing","description":"DASSET provides a third-party online document editing tool as an extension application. With this tool, you can view and edit documents stored on the DASSET device directly.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-recycle-bin":{"id":"user-guide/pc-mac/dasset-applications-recycle-bin","title":"Recycle Bin","description":"All deleted files from the DASSET device are placed in the Recycle Bin. You can restore or permanently delete files at any time.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-applications-task-center":{"id":"user-guide/pc-mac/dasset-applications-task-center","title":"Task Center","description":"All file uploads, downloads, and related operations are displayed centrally in the Task Center.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-client-settings":{"id":"user-guide/pc-mac/dasset-client-settings","title":"Client Settings & Notifications","description":"Settings","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-device-list":{"id":"user-guide/pc-mac/dasset-device-list","title":"Device List Page","description":"After completing the login process, you will enter the Device List Page. If you are accessing DASSET for the first time and have not yet added a new device, this page will be blank.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-device-management":{"id":"user-guide/pc-mac/dasset-device-management","title":"Device Management","description":"All management of DASSET devices is centralized on the Device Management page, which mainly includes the following functions:","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-disk-management":{"id":"user-guide/pc-mac/dasset-disk-management","title":"Disk Management","description":"After binding, when you enter the device for the first time, you will be prompted to perform a hard disk format:","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-file-management":{"id":"user-guide/pc-mac/dasset-file-management","title":"File Management","description":"Storage Spaces","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-file-operations":{"id":"user-guide/pc-mac/dasset-file-operations","title":"File Operations","description":"File Uploads","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-filessync-dedupe":{"id":"user-guide/pc-mac/dasset-filessync-dedupe","title":"Files Sync & Deduplication","description":"Files Sync","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-im-1-on-1-chat":{"id":"user-guide/pc-mac/dasset-im-1-on-1-chat","title":"One-on-One Chat","description":"Creating a Chat","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-im-ai-agent":{"id":"user-guide/pc-mac/dasset-im-ai-agent","title":"IM AI Agent","description":"The IM feature includes multiple AI Agent capabilities that can be invoked anytime to improve communication efficiency.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-im-calls":{"id":"user-guide/pc-mac/dasset-im-calls","title":"Voice & Video Calls","description":"In addition to text-based messaging, the IM module supports high-quality voice and video calls. You can initiate a call within a one-on-one private chat or a group conversation.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-im-group-chat":{"id":"user-guide/pc-mac/dasset-im-group-chat","title":"Group Chat","description":"DASSET IM supports creating group chats with multiple contacts, making it convenient for small teams to communicate and share information.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-im-interface-overview":{"id":"user-guide/pc-mac/dasset-im-interface-overview","title":"Chat Interface Overview","description":"After selecting a chat server, you will enter the DASSET chat interface:","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-im-select-server":{"id":"user-guide/pc-mac/dasset-im-select-server","title":"Instant Messaging (IM)","description":"DASSET IM is a fully private messaging application that runs and stores data on your DASSET device.  It provides text chat capabilities, as well as real-time translation of multiple languages, and provides voice and video call capabilities as well.  Additionally, private groups can be created enabling the ability to easily share files with the group as well a create shared task lists complete with priorities and due dates.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-installation":{"id":"user-guide/pc-mac/dasset-installation","title":"Installation and Download","description":"DASSET Download Links","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-introduction":{"id":"user-guide/pc-mac/dasset-introduction","title":"Introduction","description":"This document serves as a general guide to the DASSET feature set. Please be advised that DASSET functionality is device-specific; hardware constraints may limit the availability of certain modules. Furthermore, PlanetX Labs maintains a policy of continuous integration. Consequently, documentation images and descriptions may differ from the production environment. Users should refer to the live DASSET interface for real-time feature verification and system status.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-lite-nas":{"id":"user-guide/pc-mac/dasset-lite-nas","title":"Lite NAS","description":"Lite NAS is a unique feature of DASSET that allows your Windows or macOS computer to instantly act as a lightweight NAS. It enables seamless file interaction between the DASSET client and your computer. The key functions of Lite NAS include:","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-member-management":{"id":"user-guide/pc-mac/dasset-member-management","title":"Member Management","description":"On the Member Management page, you can manage all members and their permissions, as well as invite others to join the device.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-network-management":{"id":"user-guide/pc-mac/dasset-network-management","title":"Network Management","description":"On the Network Management page, you can configure:","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-node-configuration":{"id":"user-guide/pc-mac/dasset-node-configuration","title":"Node Configuration","description":"Node configuration allows the DASSET device to expose its local network resources (e.g., at home) for remote access. This enables users to access home network resources such as cameras, printers and other devices when they are not on the local network. Only Owners and Administrators can configure this feature.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-notes":{"id":"user-guide/pc-mac/dasset-notes","title":"AI Notes","description":"Overview","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-registration":{"id":"user-guide/pc-mac/dasset-registration","title":"Registration and Login","description":"When using DASSET for the first time, you will need to create an account. DASSET supports both mobile phone numbers and email addresses as account credentials.","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-samba":{"id":"user-guide/pc-mac/dasset-samba","title":"Network Discovery Services","description":"Samba","sidebar":"DocsSidebar"},"user-guide/pc-mac/dasset-storage-management":{"id":"user-guide/pc-mac/dasset-storage-management","title":"Storage Management","description":"The Storage Management pages allows you to view the overall storage usage of the current DASSET device, including:","sidebar":"DocsSidebar"}}}}')}}]);